// DNSimple API Helper
// Shared utilities for every @webframp/dnsimple/* model.
// Auto-generated by scripts/dnsimple-codegen — do not edit manually.

/** Base URLs for DNSimple's two API environments. */
const API_BASES = {
  production: "https://api.dnsimple.com/v2",
  sandbox: "https://api.sandbox.dnsimple.com/v2",
} as const;

/** The global arguments every generated model declares. */
export interface ApiGlobalArgs {
  /** DNSimple access token, wired from a vault with a `vault.get` expression. */
  apiToken?: string;
  /** Numeric account ID that account-scoped paths use. */
  accountId?: string;
  /** `production` (the default) or `sandbox`. */
  environment?: string;
}

/** Max pagination pages (matches the repository-wide bounded-pagination rule). */
export const MAX_PAGES = 20;

/** Items requested per page. */
export const PAGE_SIZE = 100;

/** Hard deadline for a single HTTP attempt, including draining the body. */
const REQUEST_TIMEOUT_MS = 60_000;

/**
 * Longest `Retry-After` wait the helper sleeps through. A longer wait throws
 * at once, so a workflow step fails with the reset time instead of idling for
 * up to an hour.
 */
const MAX_INLINE_RETRY_SECONDS = 60;

/** Wait used when a 429 carries no usable `Retry-After` header. */
const DEFAULT_RETRY_SECONDS = 1;

/**
 * Resolve the DNSimple access token: the apiToken global arg (wired from a
 * vault with a vault.get(...) expression) takes precedence. The
 * DNSIMPLE_TOKEN environment variable is a discouraged fallback: swamp does
 * not redact it. Throws a descriptive error when neither is set.
 */
function resolveToken(apiToken?: string): string {
  const token = (apiToken ?? Deno.env.get("DNSIMPLE_TOKEN"))?.trim();
  if (!token) {
    throw new Error(
      "DNSimple API token not set. Store it in a vault and set the apiToken " +
        "global argument to a vault.get(...) expression, e.g. " +
        '\'apiToken=${{ vault.get("dnsimple", "ACCESS_TOKEN") }}\'. The ' +
        "DNSIMPLE_TOKEN environment variable is read as a fallback, but it " +
        "is not redacted and is not recommended.",
    );
  }
  // The value never appears in this message: a token with a stray newline or
  // control character would otherwise reach swamp logs and run history.
  if (!/^[\x21-\x7e]+$/.test(token)) {
    throw new Error(
      "DNSimple API token contains whitespace or a non-printable character; " +
        "check the vaulted value for a stray newline.",
    );
  }
  return token;
}

/**
 * Return the account ID an account-scoped method substitutes for the
 * `/{account}` path segment. Throws before any request goes out when the
 * `accountId` global argument is unset: `whoami` and `list_accounts` run
 * without it, which is why the argument stays optional in the schema.
 */
export function requireAccountId(
  args: ApiGlobalArgs,
  method: string,
): string {
  if (!args.accountId) {
    throw new Error(
      `accountId is required for ${method}; run the account model's whoami ` +
        `method to find it.`,
    );
  }
  return args.accountId;
}

/** The API base URL for the model's `environment` global argument. */
function baseUrl(args: ApiGlobalArgs): string {
  return args.environment === "sandbox"
    ? API_BASES.sandbox
    : API_BASES.production;
}

/**
 * Sanitize a resource instance name for swamp's data layer.
 *
 * Swamp rejects data-artifact instance names containing "/", "\\", "..", or
 * null bytes (path-traversal protection), and reserves one name for internal
 * use. Instance names are frequently derived from caller input or
 * API-returned identifiers, so every writeResource instance name is routed
 * through this before it reaches the datastore.
 */
export function sanitizeInstanceName(name: string): string {
  const lowered = name.toLowerCase();
  const cleaned = lowered
    .replace(/[/\\]/g, "_")
    .replace(/\.\./g, "_")
    .replace(/\0/g, "");
  // Names compare case-insensitively (a DNS name is one entity in any case),
  // so lowercasing is not a change. Replacing or dropping a character is: it
  // can map two different inputs to one name, so the original's hash is kept.
  // The hash is of the lowercased input, so inputs that differ only in case
  // still give one name.
  const distinct = cleaned === lowered
    ? cleaned
    : `${cleaned}-${fastHash(lowered)}`;
  const bounded = boundName(distinct, lowered);
  // Spelled as a concatenation so the repository's reserved-name scan, which
  // reports quoted literals under scripts/, does not flag the guard itself.
  // The reserved name gets a hash rather than a bare suffix, which another
  // input could equal.
  return bounded === "late" + "st"
    ? `${bounded}-${fastHash(lowered)}`
    : bounded;
}

/** The longest instance name kept, in UTF-8 bytes; filenames cap at 255. */
const MAX_NAME_BYTES = 200;

/**
 * Keep a name within MAX_NAME_BYTES by cutting its readable part and ending
 * with a hash of the full original, so a long name stays unique.
 */
function boundName(name: string, original: string): string {
  const encoder = new TextEncoder();
  if (encoder.encode(name).length <= MAX_NAME_BYTES) return name;
  const suffix = `-${fastHash(original)}`;
  let readable = "";
  for (const ch of name) {
    if (
      encoder.encode(readable + ch + suffix).length > MAX_NAME_BYTES
    ) break;
    readable += ch;
  }
  return `${readable}${suffix}`;
}

/**
 * Synchronous 53-bit string hash (cyrb53), as 14 hex characters. Used where
 * sanitizing must stay synchronous; `shortHash` is the stronger async form.
 */
function fastHash(input: string): string {
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < input.length; i++) {
    const ch = input.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^
    Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^
    Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  const n = 4294967296 * (2097151 & h2) + (h1 >>> 0);
  return n.toString(16).padStart(14, "0");
}

/**
 * Deterministic short hash (SHA-1, first 16 hex chars) for building a
 * collision-resistant resource instance name when the natural key is a
 * variable-length list or the response carries no id.
 */
export async function shortHash(input: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-1",
    new TextEncoder().encode(input),
  );
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("")
    .slice(0, 16);
}

/**
 * Name a resource instance from a method's non-account path parameters, parent
 * first: no values give `main`, one value names itself, two read
 * `<parent>-<id>` (for example `example.com-12345` for a zone record), and
 * three or more are hashed so the name stays collision-resistant. Two values
 * where either contains `-` get a hash of the pair appended, because the
 * joined form alone cannot tell `["a-b", "c"]` from `["a", "b-c"]`.
 */
export async function instanceName(parts: unknown[]): Promise<string> {
  const strings = parts.map(String);
  if (strings.length === 0) return "main";
  if (strings.length === 1) return sanitizeInstanceName(strings[0]);
  if (strings.length === 2) {
    const joined = strings.join("-");
    return sanitizeInstanceName(
      strings.some((s) => s.includes("-"))
        ? `${joined}-${await shortHash(JSON.stringify(strings))}`
        : joined,
    );
  }
  return sanitizeInstanceName(await shortHash(JSON.stringify(strings)));
}

/**
 * Hash a method's arguments into an instance-name suffix: the keys sorted,
 * every value as a string, so `5` and `"5"` (one HTTP request) and different
 * key orders give one name.
 */
export async function hashArgs(
  args: Record<string, unknown>,
  exclude: string[],
): Promise<string> {
  const entries = Object.entries(pickBody(args, exclude))
    .map(([key, value]): [string, string] => [
      key,
      typeof value === "object" && value !== null
        ? JSON.stringify(value)
        : String(value),
    ])
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return await shortHash(JSON.stringify(entries));
}

/**
 * Parse a `Retry-After` header into whole seconds. DNSimple sends two forms: a
 * number of seconds (a failed-authentication block, up to an hour) and an HTTP
 * date (a monthly request cap). Returns undefined for a missing or malformed
 * value.
 */
export function parseRetryAfter(
  header: string | null | undefined,
  nowMs: number = Date.now(),
): number | undefined {
  if (header === null || header === undefined) return undefined;
  const value = header.trim();
  if (value === "") return undefined;
  if (/^\d+(\.\d+)?$/.test(value)) return Math.ceil(Number(value));
  const at = Date.parse(value);
  if (Number.isNaN(at)) return undefined;
  return Math.max(0, Math.ceil((at - nowMs) / 1000));
}

/** A DNSimple response: the HTTP status and the parsed JSON body, if any. */
export interface DnsimpleResponse<T> {
  status: number;
  /** The whole parsed body (`{ data, pagination, ... }`); undefined on a 204. */
  body: T | undefined;
}

/** Options for a single request. */
export interface RequestOptions {
  /** JSON request body. */
  body?: unknown;
  /** Query parameters; undefined values are skipped, arrays repeat the key. */
  query?: Record<string, string | string[] | undefined>;
}

/** DNSimple's error body: `{ message }`, plus `errors` on a 400. */
interface DnsimpleErrorBody {
  message?: string;
  errors?: Record<string, unknown>;
}

function buildUrl(
  args: ApiGlobalArgs,
  path: string,
  query?: RequestOptions["query"],
): string {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query ?? {})) {
    if (value === undefined) continue;
    if (Array.isArray(value)) {
      for (const item of value) params.append(key, item);
    } else {
      params.append(key, value);
    }
  }
  const qs = params.toString();
  return `${baseUrl(args)}${path}${qs ? `?${qs}` : ""}`;
}

/**
 * One HTTP attempt under a hard deadline. The abort signal covers both the
 * request and the body drain, so a server that sends headers and then stalls
 * cannot hang the caller.
 */
async function fetchWithTimeout(
  url: string,
  init: RequestInit,
): Promise<{ response: Response; text: string }> {
  try {
    const response = await fetch(url, {
      ...init,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
    return { response, text: await response.text() };
  } catch (err) {
    const method = init.method ?? "GET";
    if (err instanceof DOMException && err.name === "TimeoutError") {
      const timedOut =
        `DNSimple API request timed out after ${REQUEST_TIMEOUT_MS / 1000}s: ` +
        `${method} ${url}`;
      throw new Error(
        method === "GET"
          ? timedOut
          : `${timedOut}. The operation may have completed; check the ` +
            `resource before retrying.`,
      );
    }
    // A header the runtime rejects can quote its value, and the only
    // caller-supplied header value is the access token.
    if (
      err instanceof TypeError &&
      /invalid header|header (value|name)/i.test(err.message)
    ) {
      throw new Error(
        "DNSimple API request could not be sent: a request header is invalid " +
          "(check the access token for stray characters).",
      );
    }
    // A write that fails after it was sent (a reset connection) may still have
    // been processed, exactly like a timeout; a read can simply be retried.
    if (method !== "GET") {
      const reason = err instanceof Error ? err.message : String(err);
      throw new Error(
        `DNSimple API request failed: ${method} ${url}: ${reason}. The ` +
          `operation may have completed; check the resource before retrying.`,
        { cause: err },
      );
    }
    throw err;
  }
}

/** Collect `field: reason` lines from a 400 body's `errors` object. */
function fieldErrors(errors: Record<string, unknown> | undefined): string[] {
  const out: string[] = [];
  for (const [field, detail] of Object.entries(errors ?? {})) {
    const reasons = (detail as { errors?: unknown } | null)?.errors;
    if (!Array.isArray(reasons)) continue;
    for (const reason of reasons) out.push(`${field}: ${String(reason)}`);
  }
  return out;
}

/**
 * Build the message for a non-2xx response. A 400 appends each field error as
 * `field: reason`. A 402 or 412 means the account's plan or feature set cannot
 * use the operation, not that the request was malformed, so it says so.
 */
export function describeError(
  method: string,
  path: string,
  status: number,
  statusText: string,
  text: string,
): string {
  let message = text.slice(0, 500);
  let fields: string[] = [];
  try {
    const parsed = JSON.parse(text) as DnsimpleErrorBody;
    if (parsed.message) message = parsed.message;
    fields = fieldErrors(parsed.errors);
  } catch {
    // Not JSON — fall through to the raw text.
  }
  const head =
    `DNSimple API error: ${method} ${path} returned ${status} ${statusText}`
      .trimEnd();
  if (status === 402 || status === 412) {
    return `${head} (plan or feature limit; the account cannot use this ` +
      `operation): ${message}`;
  }
  return fields.length > 0
    ? `${head}: ${message} (${fields.join("; ")})`
    : `${head}: ${message}`;
}

/** Message for a 429 the helper will not wait out, with the reset time. */
function rateLimitMessage(
  method: string,
  path: string,
  response: Response,
  waitSeconds: number,
  retried: boolean,
): string {
  const reset = Number(response.headers.get("X-RateLimit-Reset"));
  const fromHeader = Number.isFinite(reset) && reset > 0
    ? new Date(reset * 1000)
    : undefined;
  const fromWait = new Date(Date.now() + waitSeconds * 1000);
  // A huge header value makes an invalid Date, whose toISOString() throws.
  const resetAt = [fromHeader, fromWait].find((d) =>
    d !== undefined && Number.isFinite(d.getTime())
  );
  const reason = retried
    ? "still rate limited after one retry"
    : `Retry-After is ${waitSeconds}s, too long to wait inside a step`;
  return `DNSimple API rate limited: ${method} ${path}; ${reason} ` +
    (resetAt
      ? `(resets at ${resetAt.toISOString()})`
      : `(resets in about ${waitSeconds}s)`);
}

/**
 * The sentence appended to an error whose outcome is unknown for a write: the
 * server may have acted before the response failed or came back unusable.
 */
const MAY_HAVE_COMPLETED =
  " The operation may have completed; check the resource before retrying.";

/** True for a method that changes state, where an unclear outcome is risky. */
function isWrite(method: string): boolean {
  return method !== "GET";
}

/**
 * Parse a successful response body as JSON. An empty body (a 204) is "no
 * content" and yields undefined; a malformed body throws an error carrying the
 * method, path and status.
 */
function parseJsonBody<T>(
  text: string,
  method: string,
  path: string,
  status: number,
): T | undefined {
  if (text.trim() === "") return undefined;
  try {
    return JSON.parse(text) as T;
  } catch (err) {
    throw new Error(
      `DNSimple API returned malformed JSON: ${method} ${path} ` +
        `(status ${status}): ${(err as Error).message}; body starts: ` +
        text.slice(0, 200) + (isWrite(method) ? `.${MAY_HAVE_COMPLETED}` : ""),
    );
  }
}

/**
 * Make one DNSimple request. Resolves the base URL from `environment`, sends
 * `Authorization: Bearer`, returns the parsed body (undefined for a 204), and
 * turns an error response into a thrown error. A 429 is retried once when the
 * `Retry-After` wait is 60 seconds or less; a longer wait throws at once.
 */
export async function dnsimpleApi<T>(
  args: ApiGlobalArgs,
  method: string,
  path: string,
  options: RequestOptions = {},
): Promise<DnsimpleResponse<T>> {
  const token = resolveToken(args.apiToken);
  const url = buildUrl(args, path, options.query);
  const headers: Record<string, string> = {
    "Authorization": `Bearer ${token}`,
    "Accept": "application/json",
  };
  if (options.body !== undefined) headers["Content-Type"] = "application/json";
  const init: RequestInit = {
    method,
    headers,
    body: options.body !== undefined ? JSON.stringify(options.body) : undefined,
  };

  for (let attempt = 0;; attempt++) {
    const { response, text } = await fetchWithTimeout(url, init);

    // A 429 is rejected before the request is processed, so retrying once is
    // safe for every method, billable POSTs included. 5xx responses and
    // timeouts are never retried: a write may have gone through.
    if (response.status === 429) {
      const waitSeconds =
        parseRetryAfter(response.headers.get("Retry-After")) ??
          DEFAULT_RETRY_SECONDS;
      if (attempt === 0 && waitSeconds <= MAX_INLINE_RETRY_SECONDS) {
        await new Promise((resolve) => setTimeout(resolve, waitSeconds * 1000));
        continue;
      }
      throw new Error(
        rateLimitMessage(method, path, response, waitSeconds, attempt > 0),
      );
    }

    if (!response.ok) {
      // A 5xx on a write may follow a committed change (a gateway timing out
      // after DNSimple acted), so it carries the same warning as a timeout.
      const unclear = isWrite(method) && response.status >= 500;
      throw new Error(
        describeError(
          method,
          path,
          response.status,
          response.statusText,
          text,
        ) +
          (unclear ? MAY_HAVE_COMPLETED : ""),
      );
    }

    return {
      status: response.status,
      body: parseJsonBody<T>(text, method, path, response.status),
    };
  }
}

/**
 * Like dnsimpleApi, for endpoints whose `data` IS the result the caller
 * stores: returns the unwrapped `data`. An empty body or a missing `data`
 * there is a gateway or server fault, not "no content", so it raises a clear
 * error instead of returning undefined for the caller to trip over.
 */
export async function dnsimpleApiData<T>(
  args: ApiGlobalArgs,
  method: string,
  path: string,
  options: RequestOptions = {},
): Promise<T> {
  const { body } = await dnsimpleApi<{ data?: T | null }>(
    args,
    method,
    path,
    options,
  );
  if (body === undefined || body === null || body.data === undefined) {
    throw new Error(
      `DNSimple API returned an empty response body: ${method} ${path}.` +
        (isWrite(method) ? MAY_HAVE_COMPLETED : ""),
    );
  }
  if (body.data === null) {
    throw new Error(
      `DNSimple API returned null data: ${method} ${path}.` +
        (isWrite(method) ? MAY_HAVE_COMPLETED : ""),
    );
  }
  return body.data;
}

/** Options for a paginated walk. */
export interface PaginatedOptions {
  /** Query parameters sent with every page. */
  query?: Record<string, string | string[] | undefined>;
  /** Property path from the response root to the results array. */
  resultsPath?: string[];
  /** Siblings of the results array to keep from the first page. */
  keep?: string[];
}

/** The outcome of a paginated walk. */
export interface PaginatedResult<T> {
  results: T[];
  /** True when the walk stopped at MAX_PAGES with pages left. */
  truncated: boolean;
  /** `total_entries` from the last page fetched, when the API sent it. */
  totalEntries?: number;
  /** The `keep` siblings from the first page. */
  kept: Record<string, unknown>;
}

/** Read a nested property by path; undefined when any step is missing. */
function valueAtPath(root: unknown, path: string[]): unknown {
  let current = root;
  for (const key of path) {
    if (current === null || typeof current !== "object") return undefined;
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

/**
 * Walk every page of a paginated list. Requests PAGE_SIZE items per page and
 * advances `page=1, 2, ...` until `current_page >= total_pages`. Stops at
 * MAX_PAGES and reports `truncated: true` with `totalEntries` when pages
 * remain, so a caller can see that results are incomplete.
 */
export async function dnsimpleApiPaginated<T>(
  args: ApiGlobalArgs,
  path: string,
  options: PaginatedOptions = {},
): Promise<PaginatedResult<T>> {
  const resultsPath = options.resultsPath ?? ["data"];
  const results: T[] = [];
  const kept: Record<string, unknown> = {};
  let truncated = false;
  let totalEntries: number | undefined;

  for (let page = 1; page <= MAX_PAGES; page++) {
    const { body } = await dnsimpleApi<Record<string, unknown>>(
      args,
      "GET",
      path,
      {
        query: {
          ...options.query,
          per_page: String(PAGE_SIZE),
          page: String(page),
        },
      },
    );
    const items = valueAtPath(body, resultsPath);
    if (!Array.isArray(items)) {
      throw new Error(
        `DNSimple API returned no array at ${resultsPath.join(".")}: ` +
          `GET ${path}`,
      );
    }
    results.push(...(items as T[]));

    if (page === 1) {
      const parent = valueAtPath(body, resultsPath.slice(0, -1)) as
        | Record<string, unknown>
        | undefined;
      for (const key of options.keep ?? []) kept[key] = parent?.[key];
    }

    const pagination = (body as { pagination?: Record<string, unknown> })
      ?.pagination;
    if (typeof pagination?.total_entries === "number") {
      totalEntries = pagination.total_entries;
    }
    const current = Number(pagination?.current_page ?? page);
    const total = Number(pagination?.total_pages ?? current);
    if (current >= total) break;
    if (page === MAX_PAGES) truncated = true;
  }

  return { results, truncated, totalEntries, kept };
}

/** Collect the provided values for `keys` from args as query parameters. */
export function buildQuery(
  args: Record<string, unknown>,
  keys: string[],
): Record<string, string | string[]> {
  const query: Record<string, string | string[]> = {};
  for (const key of keys) {
    const value = args[key];
    if (value === undefined || value === null) continue;
    query[key] = Array.isArray(value) ? value.map(String) : String(value);
  }
  return query;
}

/** Build a JSON request body from args, leaving out the excluded keys. */
export function pickBody(
  args: Record<string, unknown>,
  exclude: string[],
): Record<string, unknown> {
  const skip = new Set(exclude);
  const body: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(args)) {
    if (value !== undefined && !skip.has(key)) body[key] = value;
  }
  return body;
}
